var Q9 = [
{n:1, q:'Las fuentes del derecho en el ordenamiento jurídico español están contenidas en:', o:{a:'El artículo 1 del Código Civil.',b:'El artículo 2 del Código Civil.',c:'El artículo 3 del Código Civil.',d:'El artículo 4 del Código Civil.'}, correct:'a', why:{a:'El artículo 1 del Código Civil establece las fuentes del ordenamiento jurídico español: la ley, la costumbre y los principios generales del Derecho.'}},
{n:2, q:'Es fuente del ordenamiento jurídico español:', o:{a:'La ley.',b:'La costumbre',c:'Los principios generales del derecho.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.1 del Código Civil establece que las fuentes del ordenamiento jurídico español son la ley, la costumbre y los principios generales del Derecho.'}},
{n:3, q:'Según el art.1.2 del Código Civil, carecerán de validez las disposiciones que contradigan:', o:{a:'A los acuerdos del Consejo de Ministros.',b:'Sentencias de los Tribunales de Justicia.',c:'A otras disposiciones de rango superior.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art.1.2 del Código Civil establece que carecerán de validez las disposiciones que contradigan otra de rango superior, consagrando el principio de jerarquía normativa.'}},
{n:4, q:'Según el artículo 1.3 del Código Civil, la costumbre solo regirá:', o:{a:'En defecto de ley aplicable.',b:'En defecto de norma aplicable.',c:'En defecto de disposición aplicable.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'El art.1.3 del Código Civil establece que la costumbre solo regirá en defecto de ley aplicable, siempre que no sea contraria a la moral o al orden público y que resulte probada.'}},
{n:5, q:'Según el Código Civil, la costumbre solo regirá:', o:{a:'Cuando no sea contraria a la moral.',b:'Cuando no resulte contraria al orden público.',c:'Cuando resulte probada.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.1.3 CC establece que la costumbre regirá en defecto de ley aplicable siempre que no sea contraria a la moral ni al orden público, y que resulte probada.'}},
{n:6, q:'Los principios generales del Derecho se aplicarán:', o:{a:'En defecto de ley, de costumbre, de jurisprudencia y/o de analogía.',b:'En defecto de ley, de costumbre o de jurisprudencia.',c:'En defecto de ley o de costumbre.',d:'En defecto de ley.'}, correct:'c', why:{c:'El art.1.4 CC establece que los principios generales del Derecho se aplicarán en defecto de ley o costumbre, sin perjuicio de su carácter informador del ordenamiento jurídico.'}},
{n:7, q:'Según el Código Civil, se atribuye carácter informador del ordenamiento jurídico a...', o:{a:'Los usos interpretativos.',b:'Los Tratados Internacionales.',c:'Los principios generales del Derecho.',d:'La jurisprudencia.'}, correct:'c', why:{c:'El art.1.4 CC establece que los principios generales del Derecho informarán el ordenamiento jurídico, actuando como fuente subsidiaria y criterio de interpretación.'}},
{n:8, q:'De conformidad con lo dispuesto en el Código Civil, las normas jurídicas contenidas en los Tratados Internacionales...', o:{a:'Vinculan al Derecho Español desde el mismo momento de la firma de los mismos.',b:'No serán de aplicación directa en España en tanto no hayan pasado a formar parte del ordenamiento interno mediante su publicación íntegra en el Boletín Oficial del Estado.',c:'Son de aplicación directa en España, con las reservas y condiciones que se hayan establecido en el propio Tratado.',d:'No tienen fuerza de Ley, pero complementarán el ordenamiento jurídico español, en tanto no se opongan a las normas nacionales en vigor.'}, correct:'b', why:{b:'El art.1.5 CC establece que las normas jurídicas contenidas en los Tratados Internacionales no serán de aplicación directa en España en tanto no hayan pasado a formar parte del ordenamiento interno mediante publicación íntegra en el BOE.'}},
{n:9, q:'El contenido de los Tratados Internacionales solo puede ser derogado, modificado o suspendido:', o:{a:'En la forma prevista en los propios Tratados.',b:'Mediante ley orgánica.',c:'Mediante acuerdo del Consejo de Ministros.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art.96.1 CE y el art.1.5 CC establecen que los Tratados Internacionales solo podrán ser derogados, modificados o suspendidos en la forma prevista en los propios Tratados o de acuerdo con las normas generales del Derecho internacional.'}},
{n:10, q:'Para autorizar Tratados Internacionales en los que se atribuya a una Organización Internacional el ejercicio de competencias derivadas de la Constitución:', o:{a:'Se precisa acuerdo del Consejo de Ministros.',b:'Se debe aprobar una Ley orgánica.',c:'Se necesita autorización del Senado.',d:'Debe consultarse al pueblo español mediante referéndum.'}, correct:'b', why:{b:'El art.93 CE establece que mediante ley orgánica se podrá autorizar la celebración de tratados por los que se atribuya a una organización o institución internacional el ejercicio de competencias derivadas de la Constitución.'}},
{n:11, q:'Para la formalización y denuncia de Tratados Internacionales de carácter político o militar se necesita:', o:{a:'Acuerdo del Consejo de Ministros.',b:'Ley orgánica.',c:'Autorización del Jefe del Estado.',d:'Autorización previa de las Cortes Generales.'}, correct:'d', why:{d:'El art.94.1 CE establece que la prestación del consentimiento del Estado para obligarse por medio de tratados o convenios requerirá la previa autorización de las Cortes Generales, entre otros supuestos, los de carácter político o militar.'}},
{n:12, q:'Para la formalización y denuncia de Tratados Internacionales que afecten a la integridad territorial del Estado, se necesita:', o:{a:'Ley Orgánica.',b:'Acuerdo del Consejo de Ministros.',c:'Autorización previa de las Cortes Generales.',d:'Autorización del Jefe del Estado.'}, correct:'c', why:{c:'El art.94.1.a CE establece que los tratados que afecten a la integridad territorial del Estado requieren previa autorización de las Cortes Generales.'}},
{n:13, q:'Para la formalización y denuncia de Tratados Internacionales que afecten a los derechos y deberes fundamentales del Título I de la Constitución, se necesita:', o:{a:'Ley orgánica.',b:'Autorización previa de las Cortes Generales.',c:'Autorización del Jefe del Estado.',d:'Autorización del Gobierno.'}, correct:'b', why:{b:'El art.94.1.c CE establece que los tratados que afecten a los derechos y deberes fundamentales del Título I CE requieren previa autorización de las Cortes Generales.'}},
{n:14, q:'Para la formalización y denuncia de Tratados Internacionales que impongan obligaciones financieras para la Hacienda Pública, se necesita:', o:{a:'Acuerdo del Consejo de Ministros.',b:'Autorización del Ministerio de Economía y Hacienda.',c:'Ley Orgánica.',d:'Autorización previa de las Cortes Generales.'}, correct:'d', why:{d:'El art.94.1.d CE establece que los tratados que supongan obligaciones financieras para la Hacienda Pública requieren previa autorización de las Cortes Generales.'}},
{n:15, q:'Respecto de los Tratados Internacionales, la Constitución Española establece que:', o:{a:'Una vez publicados oficialmente en España forman parte de su ordenamiento interno.',b:'Los que contengan estipulaciones contrarias a la Constitución exigirán la previa revisión constitucional.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.96.1 CE establece que los tratados válidamente celebrados y publicados oficialmente en España forman parte del ordenamiento interno, y el art.95 CE establece que los tratados contrarios a la CE exigirán previa revisión constitucional.'}},
{n:16, q:'Para la formalización y denuncia de Tratados Internacionales que supongan modificación o derogación de alguna ley, o exijan medidas legislativas para su ejecución, se necesita:', o:{a:'Autorización previa de las Cortes Generales.',b:'Acuerdo del Gobierno.',c:'Ley Orgánica.',d:'Autorización del Jefe del Estado.'}, correct:'a', why:{a:'El art.94.1.e CE establece que los tratados que modifiquen o deroguen alguna ley o exijan medidas legislativas para su ejecución requieren previa autorización de las Cortes Generales.'}},
{n:17, q:'La celebración de un Tratado Internacional que contenga estipulaciones contrarias a la Constitución:', o:{a:'Está prohibido.',b:'Exigirá la previa revisión Constitucional.',c:'Deberá ir acompañado de un Informe del Consejo de Estado, de carácter vinculante.',d:'Es nulo de pleno derecho.'}, correct:'b', why:{b:'El art.95 CE establece que la celebración de un tratado internacional que contenga estipulaciones contrarias a la Constitución exigirá la previa revisión constitucional.'}},
{n:18, q:'El consentimiento del Estado español en los Tratados Internacionales lo otorga:', o:{a:'El Gobierno.',b:'El Rey.',c:'El Senado.',d:'El Congreso de los Diputados.'}, correct:'b', why:{b:'El art.63.2 CE establece que al Rey le corresponde manifestar el consentimiento del Estado para obligarse internacionalmente por medio de tratados, de conformidad con la Constitución y las leyes.'}},
{n:19, q:'El Tribunal Constitucional puede ser requerido para que declare si existe contradicción o no, entre el texto de un Tratado Internacional y la Constitución, a petición:', o:{a:'Del Gobierno.',b:'Del Congreso.',c:'Del Senado.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.95.2 CE establece que el Gobierno o cualquiera de las Cámaras puede requerir al TC para que declare si existe o no contradicción entre un tratado y la Constitución.'}},
{n:20, q:'La Jurisprudencia:', o:{a:'Es fuente circunstancial del ordenamiento jurídico.',b:'No es fuente directa del ordenamiento jurídico.',c:'Es un principio general del Derecho.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'Conforme al art.1.6 CC, la jurisprudencia complementará el ordenamiento jurídico con la doctrina que, de modo reiterado, establezca el Tribunal Supremo. No es fuente directa sino complementaria.'}},
{n:21, q:'La Jurisprudencia:', o:{a:'Constituye la base del ordenamiento jurídico español.',b:'Complementará el ordenamiento jurídico.',c:'Modificará el ordenamiento jurídico cuando así lo disponga una Ley Orgánica.',d:'Armonizará el ordenamiento jurídico español, y lo dotará de contenido.'}, correct:'b', why:{b:'El art.1.6 CC establece que la jurisprudencia complementará el ordenamiento jurídico con la doctrina que, de modo reiterado, establezca el Tribunal Supremo al interpretar y aplicar la ley, la costumbre y los principios generales del Derecho.'}},
{n:22, q:'El Tribunal Supremo creará jurisprudencia al interpretar y aplicar:', o:{a:'La ley.',b:'La costumbre.',c:'Los principios generales del Derecho.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.1.6 CC establece que la jurisprudencia se forma al interpretar y aplicar la ley, la costumbre y los principios generales del Derecho.'}},
{n:23, q:'Según el artículo 1.7 del Código Civil, los Jueces y Tribunales tienen el deber inexcusable de resolver en todo caso, los asuntos que conozcan...', o:{a:'Excepto en caso de recusación.',b:'Ateniéndose al sistema de fuentes establecido.',c:'En los términos que establezca una Ley Orgánica.',d:'Conforme a las reglas de procedimiento establecidas.'}, correct:'b', why:{b:'El art.1.7 CC establece que los Jueces y Tribunales tienen el deber inexcusable de resolver en todo caso los asuntos de que conozcan, ateniéndose al sistema de fuentes establecido.'}},
{n:24, q:'El principio de jerarquía normativa está establecido en...', o:{a:'El artículo 1.2 del Código Civil.',b:'El artículo 9.3 de la Constitución Española.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El principio de jerarquía normativa está recogido tanto en el art.1.2 CC (que establece que las disposiciones que contradigan otra de rango superior carecen de validez) como en el art.9.3 CE (que garantiza la jerarquía normativa).'}},
{n:25, q:'Señale la respuesta que contiene el orden de jerarquía correcto en el ordenamiento jurídico español...', o:{a:'Constitución; Leyes y normas con rango de Ley; Tratados internacionales suscritos válidamente por España; Reglamentos.',b:'Constitución; Tratados Internacionales suscritos válidamente por España; Leyes y normas con rango de Ley; Reglamentos.',c:'Constitución; Reglamentos; Leyes y normas con rango de Ley; Tratados internacionales suscritos válidamente por España.',d:'Constitución; Reglamentos; Tratados internacionales suscritos por España; Leyes y normas con rango de Ley.'}, correct:'b', why:{b:'El orden jerárquico en el ordenamiento jurídico español es: Constitución en la cúspide; Tratados Internacionales válidamente suscritos; Leyes y normas con rango de ley; Reglamentos.'}},
{n:26, q:'Las leyes :', o:{a:'Pueden ser objeto de recurso ante la jurisdicción Contencioso-Administrativa.',b:'Pueden ser objeto de recurso ante la jurisdicción ordinaria.',c:'Pueden ser objeto de recurso ante el Tribunal Constitucional.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Las leyes pueden ser objeto del recurso de inconstitucionalidad ante el Tribunal Constitucional y de la cuestión de inconstitucionalidad planteada por los jueces.'}},
{n:27, q:'En el ámbito del Estado, el órgano competente para aprobar leyes...', o:{a:'Es el Gobierno.',b:'Son las Cortes Generales.',c:'Es Congreso de los Diputados.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art.66.2 CE establece que las Cortes Generales ejercen la potestad legislativa del Estado.'}},
{n:28, q:'En nuestro ordenamiento jurídico....', o:{a:'Solo existe un tipo de ley.',b:'Las Leyes del Estado están en un plano superior a las dictadas por las Comunidades Autónomas.',c:'Existen una pluralidad de instrumentos normativos con valor y fuerza de ley, que tienen el mismo rango normativo.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'En el ordenamiento jurídico español existen múltiples tipos de normas con rango de ley (leyes orgánicas, leyes ordinarias, decretos-ley, decretos legislativos) que, con algunas matizaciones, tienen el mismo rango normativo formal.'}},
{n:29, q:'Diferencia entre ley orgánica y ley ordinaria.', o:{a:'La Ley Orgánica es aprobada por las Cortes Generales. La Ley ordinaria solo puede ser aprobada por un parlamento autonómico.',b:'En las leyes orgánicas se requiere una votación final en el Congreso. En las Leyes ordinarias se requiere una votación final en el Senado.',c:'La Ley Orgánica necesita para su aprobación mayoría de dos tercios, mientras que la Ley Ordinaria puede ser aprobada por mayoría absoluta.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'La principal diferencia es que la ley orgánica requiere mayoría absoluta del Congreso en votación final sobre el conjunto del proyecto (art.81.2 CE), mientras que la ley ordinaria solo necesita mayoría simple.'}},
{n:30, q:'Las leyes ordinarias....', o:{a:'Regulan las materias que les atribuye la Constitución Española.',b:'Se subordinan jerárquicamente a las leyes orgánicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Las leyes ordinarias regulan las materias no reservadas a ley orgánica y no se subordinan jerárquicamente a las leyes orgánicas; ambas tienen el mismo rango, diferenciándose por la materia y el procedimiento.'}},
{n:31, q:'Si una ley ordinaria regulase materias que corresponden a una ley orgánica:', o:{a:'Incurriría en vicio de inconstitucionalidad por incompetencia formal.',b:'Incurriría en vicio de inconstitucionalidad por incompetencia material.',c:'Incurriría en vicio de inconstitucionalidad por incompetencia absoluta.',d:'Podría ser subsanada por medio de un Real Decreto Legislativo.'}, correct:'b', why:{b:'Si una ley ordinaria regula materias reservadas a ley orgánica, incurriría en un vicio de inconstitucionalidad por incompetencia material (la materia está reservada a otro tipo normativo).'}},
{n:32, q:'Una ley ordinaria:', o:{a:'Puede modificar una ley orgánica, si así lo autoriza el Congreso de los Diputados.',b:'Puede modificar una ley orgánica en los casos y forma establecidos en el Título III de la Constitución Española.',c:'No puede modificar una ley orgánica.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Una ley ordinaria no puede modificar ni derogar una ley orgánica, porque la ley orgánica requiere mayoría absoluta del Congreso para su aprobación, modificación o derogación.'}},
{n:33, q:'La relación entre una ley orgánica y una ley ordinaria se rige por el principio de:', o:{a:'Jerarquía.',b:'Competencia.',c:'Subsidiariedad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La relación entre ley orgánica y ley ordinaria se rige principalmente por el principio de competencia (cada una regula materias reservadas por la CE) y no por jerarquía, ya que formalmente tienen el mismo rango.'}},
{n:34, q:'Indique la respuesta correcta:', o:{a:'Las leyes orgánicas pueden ser objeto de aprobación por el Gobierno, en caso de extraordinaria y urgente necesidad.',b:'Las leyes orgánicas pueden aprobarse en Comisión.',c:'Las leyes ordinarias pueden aprobarse en Pleno o en Comisión.',d:'Una ley ordinaria no puede modificar una ley orgánica.'}, correct:'d', why:{d:'Una ley ordinaria no puede modificar una ley orgánica, ya que esta requiere mayoría absoluta del Congreso. Las leyes ordinarias pueden delegarse en comisiones; las orgánicas no.'}},
{n:35, q:'Según el artículo 81 de la Constitución Española, son Leyes orgánicas...', o:{a:'Las que aprueban los Estatutos de Autonomía.',b:'Las que aprueban el régimen electoral general.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.81.1 CE establece que son leyes orgánicas las relativas al desarrollo de los derechos fundamentales y libertades públicas, las que aprueben los Estatutos de Autonomía y el régimen electoral general, y las demás previstas en la Constitución.'}},
{n:36, q:'Según el artículo 81 de la Constitución Española, son Leyes orgánicas...', o:{a:'Las que aprueban los Presupuestos Generales del Estado.',b:'Las relativas al desarrollo de derechos fundamentales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.81.1 CE establece que son leyes orgánicas las relativas al desarrollo de los derechos fundamentales y de las libertades públicas.'}},
{n:37, q:'Según el artículo 81 de la Constitución Española, son Leyes orgánicas...', o:{a:'Las que sean necesarias para delegar en el Gobierno la potestad de dictar normas con rango de Ley.',b:'Las previstas en la Constitución.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.81.1 CE establece que son leyes orgánicas las relativas a los ámbitos previstos en la Constitución, además de las de derechos fundamentales, estatutos de autonomía y régimen electoral general.'}},
{n:38, q:'Se requiere mayoría absoluta del Congreso para...', o:{a:'Aprobar una Ley orgánica.',b:'Aprobar una Ley ordinaria.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.81.2 CE establece que la aprobación, modificación o derogación de las leyes orgánicas exige mayoría absoluta del Congreso, en una votación final sobre el conjunto del proyecto.'}},
{n:39, q:'Se requiere mayoría absoluta del Congreso para...', o:{a:'Modificar una Ley orgánica.',b:'Renovar los órganos constitucionales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.81.2 CE establece que la aprobación, modificación o derogación de las leyes orgánicas exige mayoría absoluta del Congreso. Modificar una ley orgánica requiere mayoría absoluta del Congreso.'}},
{n:40, q:'Aquellas leyes, constituidas por un conjunto de criterios, que el legislador pone a disposición del Gobierno, para que éste regule una determinada materia, se denominan:', o:{a:'Leyes orgánicas.',b:'Leyes básicas.',c:'Leyes ordinarias.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Las leyes de bases son aquellas que contienen un conjunto de criterios o directrices que el legislador pone a disposición del Gobierno para que este dicte el texto articulado mediante decreto legislativo.'}},
{n:41, q:'Aquellas leyes, constituidas por un conjunto de criterios, que el legislador pone a disposición del Gobierno, para que éste regule una determinada materia, se denominan:', o:{a:'Leyes marco.',b:'Leyes básicas.',c:'Leyes de bases.',d:'Leyes de armonización.'}, correct:'c', why:{c:'Las leyes de bases son aquellas que contienen los principios y criterios a los que debe ajustarse el texto articulado que dicte el Gobierno mediante decreto legislativo.'}},
{n:42, q:'Aquellas leyes dictadas por los órganos legislativos del Estado para que las Comunidades Autónomas las desarrollen mediante leyes de la propia Comunidad, se denominan:', o:{a:'Leyes marco.',b:'Leyes de bases.',c:'Leyes básicas.',d:'Leyes de armonización.'}, correct:'c', why:{c:'Las leyes marco son aquellas en las que las Cortes Generales establecen los principios en una materia, atribuyendo a las CCAA la facultad de dictar normas legislativas en dicho marco (art.150.1 CE).'}},
{n:43, q:'Las leyes que tienen por objeto ordenar la relación entre la competencia legislativa del Estado y la de las Comunidades Autónomas, se denominan:', o:{a:'Leyes marco.',b:'Leyes de bases.',c:'Leyes básicas.',d:'Leyes de armonización.'}, correct:'a', why:{a:'Las leyes de armonización son aquellas por las que el Estado establece los principios necesarios para armonizar las disposiciones normativas de las CCAA, aun en materias de competencia de éstas, cuando así lo exija el interés general (art.150.3 CE).'}},
{n:44, q:'Las leyes marco atribuyen a las comunidades Autónomas la facultad de dictar, para sí mismas, normas legislativas sobre aquellas competencias que son:', o:{a:'De las propias Comunidades Autónomas.',b:'Del Estado.',c:'De la Administración Local.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Las leyes marco (art.150.1 CE) son aquellas por las que las Cortes Generales pueden atribuir a las CCAA, en materias de competencia estatal, la facultad de dictar para sí mismas normas legislativas en el marco de los principios establecidos en la ley marco.'}},
{n:45, q:'El control sobre las normas que dicte una Comunidad Autónoma, con relación a una ley marco, lo ejercen:', o:{a:'Los Tribunales de justicia.',b:'Las Asambleas Legislativas.',c:'Las Cortes Generales.',d:'Las respuestas a y c son correctas.'}, correct:'d', why:{d:'El control de las normas autonómicas dictadas al amparo de una ley marco corresponde a las Cortes Generales y a los Tribunales de justicia.'}},
{n:46, q:'Las leyes de armonización se producirán:', o:{a:'Cuando el poder legislativo quiera delegar la aprobación de una ley a una Comunidad Autónoma.',b:'Cuando las Cortes Generales quieran delegar la aprobación de un Decreto legislativo al gobierno.',c:'Cuando las Cortes Generales deseen ordenar la relación entre la competencia legislativa del Estado y la de las Comunidades Autónomas.',d:'Cuando exista un interés nacional que así lo demande.'}, correct:'d', why:{d:'Las leyes de armonización del art.150.3 CE se dictan cuando las Cortes Generales estiman necesario armonizar las disposiciones normativas de las CCAA, aun en materias de competencia autonómica, por exigirlo el interés general.'}},
{n:47, q:'Las Leyes de armonización van dirigidas a:', o:{a:'Las Comunidades Autónomas.',b:'Las Corporaciones Locales.',c:'El Gobierno.',d:'El Senado.'}, correct:'a', why:{a:'Las leyes de armonización van dirigidas a las Comunidades Autónomas, para que armonicen sus disposiciones normativas en materias donde el interés general lo exija.'}},
{n:48, q:'El ámbito material que pretende armonizar una ley de armonización, está referido a:', o:{a:'Las competencias exclusivas de las Comunidades Autónomas.',b:'Las competencias compartidas de las Comunidades Autónomas.',c:'Las competencias que posean las Comunidades Autónomas en base a leyes marco.',d:'Todas las competencias reflejadas en las respuestas anteriores.'}, correct:'d', why:{d:'Las leyes de armonización pueden referirse tanto a las competencias exclusivas autonómicas como a las compartidas o basadas en leyes marco, siempre que el interés general lo exija.'}},
{n:49, q:'Las leyes de armonización tienen por objeto:', o:{a:'Que las Comunidades Autónomas no sobrepasen los límites competenciales que les corresponden.',b:'Que las Comunidades Autónomas compartan su función legislativa con el Estado.',c:'Que las Comunidades Autónomas no sobrepasen los límites de endeudamiento fijados por el Estado.',d:'Que las Comunidades Autónomas se sometan a unos principios de coincidencia para dar satisfacción a los intereses generales.'}, correct:'d', why:{d:'Las leyes de armonización tienen por objeto que las CCAA se sometan a unos principios comunes para satisfacer los intereses generales del conjunto del Estado.'}},
{n:50, q:'Las leyes de armonización pueden dirigirse a las Comunidades Autónomas para que armonicen sus disposiciones normativas, en el caso de competencias:', o:{a:'Del Estado.',b:'De las Comunidades Autónomas.',c:'Del Estado o de las propias Comunidades Autónomas.',d:'Del Estado, de las Comunidades Autónomas o de las Corporaciones Locales.'}, correct:'c', why:{c:'El art.150.3 CE establece que el Estado puede dictar leyes de armonización de las disposiciones normativas de las CCAA, incluso cuando se trate de materias atribuidas a la competencia de éstas.'}},
{n:51, q:'Las leyes de armonización precisan la aprobación de:', o:{a:'Ambas Cámaras, Congreso y Senado, por mayoría simple.',b:'Ambas Cámaras, Congreso y Senado, por mayoría de 2/3.',c:'Ambas Cámaras, Congreso y Senado, por mayoría absoluta.',d:'El Congreso de los diputados por mayoría absoluta.'}, correct:'c', why:{c:'El art.150.3 CE establece que las leyes de armonización deben ser aprobadas por mayoría absoluta de cada una de las Cámaras.'}},
{n:52, q:'En caso de discrepancia entre el contenido en una ley estatal y otra autonómica:', o:{a:'Siempre prevalece la ley estatal.',b:'Prevalece la dictada por la administración que tenga asumida la competencia de que se trate.',c:'La Ley estatal siempre será la legislación básica, mientras que la autonómica se aplicará con carácter supletorio.',d:'Siempre prevalecerá la ley de la comunidad autónoma respectiva en virtud del principio constitucional de autonomía.'}, correct:'b', why:{b:'En caso de discrepancia entre ley estatal y autonómica prevalece la norma del ente que tenga atribuida la competencia en esa materia, conforme al sistema de distribución de competencias.'}},
{n:53, q:'Las Cortes Generales podrán delegar la potestad de dictar normas con rango de ley sobre materias determinadas:', o:{a:'Al Gobierno.',b:'A las Comunidades Autónomas.',c:'A las Corporaciones Locales.',d:'A cualquiera de los citados en las respuestas anteriores.'}, correct:'c', why:{c:'El art.82 CE establece que las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normas con rango de ley sobre materias determinadas no incluidas en el artículo anterior.'}},
{n:54, q:'El Gobierno puede dictar normas con rango de ley sobre materias determinadas, siempre que:', o:{a:'No se trate de materias que afecten a los Presupuestos Generales del Estado.',b:'No se trate de materias que afecten a la seguridad de los trabajadores.',c:'No se trate de materias que precisen dictamen del Consejo de Estado.',d:'No se trate de materias que deban ser reguladas por ley orgánica.'}, correct:'d', why:{d:'El art.82.1 CE establece que la delegación legislativa en el Gobierno no podrá comprender materias que deban regularse por ley orgánica.'}},
{n:55, q:'Se denomina legislación delegada:', o:{a:'A las normas que dictan las Comunidades Autónomas sobre competencias estatales.',b:'A las normas con rango y fuerza de ley que dicta el Gobierno por delegación de las Cortes Generales.',c:'A las normas dictadas por las Comisiones Delegadas del Gobierno, en función de una delegación previa que realiza éste.',d:'A las normas aprobadas por el Presidente del Gobierno en virtud de una delegación previa de las Cortes Generales.'}, correct:'b', why:{b:'La legislación delegada son las normas con rango y fuerza de ley dictadas por el Gobierno en virtud de una delegación expresa y previa de las Cortes Generales, tomando la forma de decretos legislativos.'}},
{n:56, q:'Las leyes de bases delimitarán con precisión...', o:{a:'El objeto y alcance de la delegación legislativa.',b:'El procedimiento de aprobación de las normas con fuerza de ley.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.83 CE establece que las leyes de bases delimitarán con precisión el objeto y alcance de la delegación legislativa y los principios y criterios que han de seguirse en su ejercicio.'}},
{n:57, q:'Las disposiciones del Gobierno que contienen legislación delegada, reciben el nombre de:', o:{a:'Decretos leyes.',b:'Decretos legislativos.',c:'Leyes de bases.',d:'Leyes básicas.'}, correct:'b', why:{b:'El art.85 CE establece que las disposiciones del Gobierno que contengan legislación delegada recibirán el título de decretos legislativos.'}},
{n:58, q:'La Delegación legislativa:', o:{a:'Requiere de la aceptación del Gobierno, expresada mediante Decreto del Consejo de Ministros.',b:'Debe otorgarse de forma expresa para materia concreta, con fijación del plazo para su ejercicio.',c:'Se puede hacer por tiempo indeterminado, cuando se defina claramente el objeto de dicha delegación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art.82.3 CE establece que la delegación legislativa habrá de otorgarse de forma expresa para materia concreta y con fijación del plazo para su ejercicio.'}},
{n:59, q:'Una vez concedida una delegación legislativa:', o:{a:'El Gobierno debe hacer uso de ella en el plazo de seis meses.',b:'El Gobierno puede hacer uso de ella por tiempo indeterminado.',c:'El Gobierno debe hacer uso de ella en el plazo indicado en la misma.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La delegación legislativa debe ejercerse en el plazo señalado expresamente en la ley delegante; si no se ejerce en ese plazo, caduca.'}},
{n:60, q:'El control de los excesos de delegación legislativa corresponde a:', o:{a:'El Tribunal Constitucional.',b:'La jurisdicción ordinaria.',c:'Las Cortes Generales.',d:'Los citados en las respuestas a y b.'}, correct:'d', why:{d:'El control de los excesos de la delegación legislativa corresponde tanto a los Tribunales ordinarios como al Tribunal Constitucional.'}},
{n:61, q:'Cuando la delegación legislativa tenga por objeto la formación de textos articulados, se otorgará mediante:', o:{a:'Ley orgánica.',b:'Ley ordinaria.',c:'Ley de bases.',d:'Ley de armonización.'}, correct:'c', why:{c:'El art.82.2 CE establece que la delegación legislativa se otorgará mediante ley de bases cuando su objeto sea la formación de textos articulados.'}},
{n:62, q:'Cuando la delegación legislativa tenga por objeto refundir varios textos legales en uno solo, se otorgará mediante:', o:{a:'Ley orgánica.',b:'Ley ordinaria.',c:'Ley de bases.',d:'Ley básica.'}, correct:'b', why:{b:'El art.82.2 CE establece que la delegación legislativa se otorgará mediante ley ordinaria cuando su objeto sea la refundición de varios textos legales en uno solo.'}},
{n:63, q:'La delegación legislativa realizada por las Cortes Generales...', o:{a:'Se agota por el uso que ella haga el Gobierno mediante la publicación de la norma correspondiente.',b:'No puede entenderse concedida por tiempo indeterminado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La delegación legislativa se agota con el uso que de ella haga el Gobierno mediante la publicación de la norma correspondiente y no puede entenderse concedida por tiempo indeterminado.'}},
{n:64, q:'La delegación legislativa realizada por las Cortes Generales...', o:{a:'Puede autorizar la subdelegación de aprobación de la norma en autoridades distintas del propio Gobierno.',b:'Está prohibida cuando la finalidad de la norma sea refundir varios textos legales en uno solo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La delegación legislativa no puede ser objeto de subdelegación en autoridades distintas del Gobierno (art.82.3 CE), y no está prohibida para refundición de textos.'}},
{n:65, q:'Las leyes de bases...', o:{a:'Delimitarán con precisión los principios y criterios que han de seguirse.',b:'Podrán autorizar la modificación de la propia Ley de Bases por el Gobierno.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.83 CE establece que las leyes de bases delimitarán con precisión el objeto y alcance de la delegación legislativa y los principios y criterios que han de seguirse. No pueden autorizar al Gobierno a modificar la propia ley de bases.'}},
{n:66, q:'En una ley de bases:', o:{a:'Se puede facultar al Gobierno para que dicte normas con carácter retroactivo.',b:'No se puede facultar al Gobierno para que dicte normas con carácter retroactivo.',c:'Se puede facultar al Gobierno para que dicte normas con carácter retroactivo siempre que estas normas sean favorables a los interesados.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art.83.c CE establece que las leyes de bases no pueden facultar al Gobierno para dictar normas con carácter retroactivo.'}},
{n:67, q:'Antes de la aprobación de un texto articulado:', o:{a:'Se precisa dictamen preceptivo del Consejo de Estado en Pleno.',b:'Se precisa dictamen facultativo del Consejo de Estado en Pleno.',c:'Se precisa dictamen preceptivo del Consejo de Estado, en Pleno o en Comisión.',d:'Se precisa dictamen facultativo del Consejo de Estado, en Pleno o en Comisión.'}, correct:'a', why:{a:'La Ley Orgánica del Consejo de Estado establece que antes de la aprobación de un texto articulado o de un texto refundido, es preceptivo el dictamen del Consejo de Estado en Pleno.'}},
{n:68, q:'En la autorización para producir textos refundidos, se puede autorizar al Gobierno:', o:{a:'A regularizar, aclarar y armonizar los textos legales que vayan a ser refundidos.',b:'A regular en el futuro todo lo concerniente a la materia de que se trate.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.82.5 CE establece que la autorización para refundir textos legales puede determinar el alcance de la delegación y puede comprender regularizar, aclarar y armonizar los textos refundidos.'}},
{n:69, q:'Cuando una proposición de ley o una enmienda fuere contraria a una delegación legislativa, el Gobierno...', o:{a:'Entenderá que la delegación legislativa ha quedado sin efecto.',b:'Podrá solicitar al Congreso de los Diputados la adopción de un proyecto de ley sobre la misma materia.',c:'Está facultado para oponerse a su tramitación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art.84 CE establece que cuando una proposición de ley o una enmienda fuere contraria a una delegación legislativa en vigor, el Gobierno está facultado para oponerse a su tramitación.'}},
{n:70, q:'Cuando una proposición de ley o una enmienda fuere contraria a una delegación legislativa...', o:{a:'Podrá presentarse una proposición de ley para la derogación total o parcial de la ley de delegación.',b:'El Gobierno no puede oponerse a su tramitación.',c:'El Gobierno puede acordar con el Senado su tramitación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art.84 CE establece que en caso de oposición gubernamental a la tramitación de una proposición de ley contraria a una delegación, la proposición de ley puede tomarse en consideración si se solicita también la derogación de la ley de delegación.'}},
{n:71, q:'El Gobierno podrá dictar Decretos-ley:', o:{a:'Durante los estados de alarma, excepción y sitio.',b:'En casos de extraordinaria y urgente necesidad.',c:'En los periodos de tiempo en que no estén funcionando las Cortes Generales.',d:'En todos los supuestos citados en las respuestas anteriores.'}, correct:'b', why:{b:'El art.86.1 CE establece que en casos de extraordinaria y urgente necesidad, el Gobierno podrá dictar disposiciones legislativas provisionales que tomarán la forma de Decretos-leyes.'}},
{n:72, q:'La Constitución Española, en su art.86.1, establece que los Decretos-ley son:', o:{a:'Disposiciones legislativas facultativas.',b:'Disposiciones reglamentarias preceptivas.',c:'Disposiciones reglamentarias provisionales.',d:'Disposiciones legislativas provisionales.'}, correct:'d', why:{d:'El art.86.1 CE establece que los Decretos-leyes son disposiciones legislativas provisionales que puede dictar el Gobierno en casos de extraordinaria y urgente necesidad.'}},
{n:73, q:'No se puede regular por Decreto-ley, lo referente:', o:{a:'Al Derecho electoral general.',b:'Al acceso a los archivos y registros.',c:'A las competencias de las corporaciones locales.',d:'A ninguna de las materias citadas en las respuestas anteriores.'}, correct:'a', why:{a:'El art.86.1 CE establece que los Decretos-leyes no podrán afectar al ordenamiento de las instituciones básicas del Estado, a los derechos del Título I, al régimen de las CCAA, ni al Derecho electoral general.'}},
{n:74, q:'No se puede regular mediante Decreto-ley:', o:{a:'Lo referente al régimen de las Comunidades Autónomas.',b:'Los derechos y libertades de los ciudadanos, regulados en el Título I de la Constitución.',c:'El ordenamiento de las instituciones básicas del Estado.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.86.1 CE establece que los Decretos-leyes no podrán afectar al ordenamiento de las instituciones básicas del Estado, a los derechos y libertades del Título I CE, ni al régimen de las CCAA, ni al Derecho electoral general.'}},
{n:75, q:'Según el art. 86 de la Constitución Española, los Decretos-ley deberán ser inmediatamente sometidos a debate y votación de totalidad al Congreso de los Diputados, convocado al efecto si no estuviere reunido, en el plazo de los...', o:{a:'El Congreso de los Diputados.',b:'El Congreso de los Diputados y el Senado.',c:'El Consejo de Ministros.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art.86.2 CE establece que los Decretos-leyes deberán ser sometidos inmediatamente al Congreso de los Diputados, convocado al efecto si no estuviere reunido, para su debate y votación en el plazo de los treinta días siguientes a su promulgación.'}},
{n:76, q:'En caso de que el Congreso de los Diputados no estuviere reunido cuando se apruebe un Decreto-ley:', o:{a:'Será convocado al efecto en el plazo de los 15 días siguientes a su promulgación.',b:'Será convocado al efecto en el plazo de los 20 días siguientes a su promulgación.',c:'Será convocado al efecto en el plazo de los 30 días siguientes a su promulgación.',d:'Será convocado al efecto en el plazo de los dos meses siguientes a su promulgación.'}, correct:'c', why:{c:'El art.86.2 CE establece que el Congreso deberá pronunciarse en el plazo de los treinta días siguientes a la promulgación del Decreto-ley, y si no estuviere reunido será convocado al efecto.'}},
{n:77, q:'Las Cortes Generales, durante los 30 días siguientes a la promulgación de un Decreto-ley:', o:{a:'Podrán introducir las correcciones y recomendaciones que estimen convenientes.',b:'Podrán tramitar su contenido como proyecto de ley por el procedimiento de urgencia.',c:'Podrán someterlo a dictamen del Consejo de Estado.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art.86.3 CE establece que durante el plazo de los treinta días, las Cámaras podrán tramitar los decretos-leyes como proyectos de ley por el procedimiento de urgencia.'}},
{n:78, q:'La potestad reglamentaria:', o:{a:'Solo corresponde a los órganos que la tienen expresa o tácitamente atribuida.',b:'Solo corresponde a los órganos que la tengan expresamente atribuida.',c:'Solo corresponde a los órganos que conforme a la Constitución la tienen atribuida.',d:'Solo corresponde al Gobierno del Estado y a los órganos ejecutivos de las Comunidades Autónomas.'}, correct:'b', why:{b:'La potestad reglamentaria corresponde a los órganos que la tienen expresamente atribuida, conforme a la Constitución y las leyes, siendo el Gobierno el titular principal de esta potestad.'}},
{n:79, q:'La potestad reglamentaria que corresponde al Gobierno de la nación viene atribuida en...', o:{a:'El artículo 143 de la Constitución Española.',b:'El artículo 97 de la Constitución Española.',c:'El artículo 137 de la Constitución Española.',d:'Los artículos 140 y 141 de la Constitución Española.'}, correct:'b', why:{b:'El art.97 CE establece que el Gobierno ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.'}},
{n:80, q:'En lo que respecta a los reglamentos, indique la respuesta correcta:', o:{a:'Existe una pluralidad de reglamentos.',b:'Son reglamentos de rango superior el Real Decreto Ley y el Real Decreto Legislativo.',c:'El rango de algunos reglamentos equivale a una ley ordinaria, en determinados casos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'En el ordenamiento jurídico español existe una pluralidad de reglamentos de distinto rango: Reales Decretos del Consejo de Ministros, Órdenes Ministeriales, Resoluciones, etc.'}},
{n:81, q:'El nivel jerárquico de los reglamentos depende...', o:{a:'De la jerarquía del órgano que los ha dictado.',b:'Del orden de preeminencia establecido en la Constitución Española.',c:'De la calificación otorgada por los destinatarios del reglamento.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El nivel jerárquico de los reglamentos depende de la jerarquía del órgano que los dicta: los Reales Decretos del Consejo de Ministros son superiores a las Órdenes Ministeriales, que son superiores a las Resoluciones.'}},
{n:82, q:'En el ámbito de la Administración General del Estado, la jerarquía de los reglamentos se establece en...', o:{a:'El artículo 24.2 de la Ley 39/2015.',b:'El artículo 24.2 de la Ley 40/2015.',c:'El artículo 24.2 de la Ley 50/1997.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La jerarquía de los reglamentos en el ámbito de la Administración General del Estado se establece en el art.24.2 de la Ley 50/1997, del Gobierno.'}},
{n:83, q:'En el ámbito de la Administración General del Estado, respecto de la jerarquía de los reglamentos, el artículo 24.2 de la Ley 50/1997 dispone que:', o:{a:'En primer lugar están las disposiciones aprobadas por Real Decreto del Presidente del Gobierno o acordado en Consejo de Ministros.',b:'En segundo lugar están las disposiciones aprobadas por orden ministerial.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.24.2 de la Ley 50/1997, del Gobierno, establece la jerarquía de los reglamentos: primero los Reales Decretos del Presidente o acordados en Consejo de Ministros, y en segundo lugar las Órdenes Ministeriales.'}},
{n:84, q:'Las disposiciones administrativas del Estado:', o:{a:'No pueden vulnerar la Constitución ni las leyes estatales.',b:'No pueden regular aquellas materias que los Estatutos de Autonomía reconocen a las Asambleas Legislativas de las Comunidades Autónomas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Las disposiciones administrativas no pueden vulnerar la Constitución ni las leyes estatales, ni regular materias reservadas a las CCAA por sus Estatutos.'}},
{n:85, q:'Por su procedencia, los Reglamentos se clasifican en:', o:{a:'Estatales, autonómicos, locales e institucionales.',b:'Estatales, autonómicos y locales.',c:'Ejecutivos, independientes y de necesidad.',d:'Excepcionales y generales.'}, correct:'b', why:{b:'Por su procedencia o ámbito territorial, los reglamentos se clasifican en estatales, autonómicos y locales.'}},
{n:86, q:'Por sus efectos, los Reglamentos se clasifican en:', o:{a:'Estatales, autonómicos o locales.',b:'Ejecutivos, independientes y de necesidad.',c:'Jurídicos o normativos y administrativos o de organización.',d:'Generales y excepcionales.'}, correct:'c', why:{c:'Por sus efectos jurídicos, los reglamentos se clasifican en: jurídicos o normativos (que afectan a los ciudadanos) y administrativos o de organización (que regulan el funcionamiento interno de la Administración).'}},
{n:87, q:'Por su relación con la ley, los Reglamentos se clasifican en:', o:{a:'Estatales, autonómicos y locales.',b:'Ejecutivos, independientes y de necesidad.',c:'Jurídicos o normativos y administrativos o de organización.',d:'Generales y particulares.'}, correct:'b', why:{b:'Por su relación con la ley, los reglamentos se clasifican en: ejecutivos o de desarrollo (complementan la ley), independientes (regulan materias no cubiertas por ley) y de necesidad (dictados ante situaciones de emergencia).'}},
{n:88, q:'Por razón de sus destinatarios, los Reglamentos se clasifican en:', o:{a:'Estatales, autonómicos o locales.',b:'Ejecutivos, independientes o de necesidad.',c:'Jurídicos o normativos y administrativos o de organización.',d:'Generales o particulares.'}, correct:'d', why:{d:'Por razón de sus destinatarios, los reglamentos se clasifican en generales (dirigidos a la generalidad de los ciudadanos) o particulares (dirigidos a sujetos en una relación especial con la Administración).'}},
{n:89, q:'Aquellos Reglamentos dictados en virtud de las remisiones que realiza una ley, se denominan:', o:{a:'Ejecutivos.',b:'Independientes.',c:'Excepcionales.',d:'Normativos.'}, correct:'a', why:{a:'Los reglamentos ejecutivos son aquellos dictados para desarrollar, complementar o aplicar lo dispuesto en una ley, en virtud de la remisión que la propia ley hace al reglamento.'}},
{n:90, q:'Los Reglamentos Independientes de la ley solo se permiten:', o:{a:'En ningún caso.',b:'En materias de organización.',c:'Cuando la materia no está reservada a ley orgánica.',d:'En situaciones excepcionales.'}, correct:'b', why:{b:'Los reglamentos independientes solo se permiten en materias de organización interna de la Administración, ya que en las materias que afectan a los ciudadanos se requiere habilitación legal previa.'}},
{n:91, q:'Los Reglamentos que se producen ante situaciones excepcionales y de emergencia se denominan:', o:{a:'Jurídicos.',b:'Normativos.',c:'De necesidad.',d:'Independientes.'}, correct:'c', why:{c:'Los reglamentos de necesidad son aquellos dictados ante situaciones excepcionales y de emergencia, en virtud de la potestad de la autoridad para adoptar medidas extraordinarias.'}},
{n:92, q:'Los Reglamentos que van dirigidos a la totalidad de los ciudadanos se denominan:', o:{a:'Administrativos.',b:'De organización.',c:'Generales.',d:'Ejecutivos.'}, correct:'c', why:{c:'Los reglamentos generales son los que van dirigidos a la totalidad de los ciudadanos, a diferencia de los ejecutivos o de organización que regulan relaciones internas o de desarrollo de leyes.'}},
{n:93, q:'Aquellos Reglamentos que están dirigidos a quienes estén en una singular relación con la Administración, reciben el nombre de:', o:{a:'Generales.',b:'Especiales.',c:'Ejecutivos.',d:'Administrativos.'}, correct:'b', why:{b:'Los reglamentos especiales o particulares son aquellos dirigidos a personas que se encuentran en una relación especial con la Administración (funcionarios, contratistas, etc.).'}},
{n:94, q:'Los Reglamentos no pueden regular:', o:{a:'Materias para las que se exige ley formal.',b:'Reglas de convivencia ciudadana.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Los reglamentos no pueden regular materias para las que la Constitución o las leyes exigen norma con rango de ley formal, ya que ello vulneraría el principio de reserva de ley.'}},
{n:95, q:'No puede ser objeto de regulación reglamentaria:', o:{a:'La imposición de prestaciones personales obligatorias.',b:'El establecimiento de un tributo.',c:'La limitación de una situación jurídica adquirida por un particular.',d:'Ninguna de las cuestiones citadas en las respuestas anteriores.'}, correct:'d', why:{d:'Ninguna de esas materias puede ser regulada reglamentariamente sin cobertura legal previa. La imposición de tributos, prestaciones personales obligatorias y la limitación de situaciones jurídicas adquiridas requieren habilitación legal.'}},
{n:96, q:'La potestad reglamentaria de los Ayuntamientos se realizará a través de:', o:{a:'Ordenanzas, Reglamentos y Bandos.',b:'Decretos, Resoluciones e Informes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La potestad reglamentaria de los Ayuntamientos se ejerce a través de Ordenanzas (normas generales con eficacia externa), Reglamentos (de organización interna) y Bandos (disposiciones del Alcalde).'}},
{n:97, q:'En los Ayuntamientos ¿qué órgano es el encargado de aprobar las Ordenanzas y Reglamentos?', o:{a:'La Junta de Gobierno Local.',b:'El Ayuntamiento Pleno.',c:'El Alcalde.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'Conforme a la LBRL, la aprobación de Ordenanzas y Reglamentos municipales es competencia del Pleno del Ayuntamiento.'}},
{n:98, q:'¿Cuál es el límite material de la potestad reglamentaria que tienen los municipios?', o:{a:'Las propias Ordenanzas y Reglamentos.',b:'Las competencias que legalmente tienen atribuidas.',c:'No existe ningún límite material a esta potestad.',d:'Su término municipal.'}, correct:'b', why:{b:'El límite material de la potestad reglamentaria municipal son las competencias que les atribuyen las leyes; los municipios solo pueden regular mediante Ordenanzas y Reglamentos las materias de su competencia.'}},
{n:99, q:'Por medio de las Ordenanzas Municipales se pueden imponer limitaciones al ejercicio de un determinado derecho fundamental, en espacios municipales:', o:{a:'Sí.',b:'No.',c:'Solo cuando no exista ley que lo regule.',d:'Solo en caso de catástrofe o calamidad.'}, correct:'b', why:{b:'Las Ordenanzas Municipales no pueden limitar el ejercicio de derechos fundamentales, ya que esta materia está reservada a ley orgánica por el art.53.1 CE.'}},
{n:100, q:'Con carácter previo a la aprobación inicial de una ordenanza o reglamento:', o:{a:'Se solicita informe a la Dirección General de Administración Local.',b:'Se remite borrador a la Consellería de Administraciones Públicas, que dispone de 15 días para formular alegaciones.',c:'Se somete el proyecto de ordenanza al dictamen de la comisión informativa correspondiente.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'Conforme a la LBRL, con carácter previo a la aprobación inicial de una ordenanza o reglamento, se somete el proyecto al dictamen de la comisión informativa correspondiente.'}},
{n:101, q:'El dictamen emitido por la comisión informativa correspondiente sobre un proyecto de ordenanza municipal...', o:{a:'Tiene carácter facultativo y no vinculante.',b:'Tiene carácter preceptivo y no vinculante.',c:'Tienen carácter facultativo y vinculante.',d:'Tiene carácter preceptivo y vinculante.'}, correct:'b', why:{b:'El dictamen de la comisión informativa sobre un proyecto de ordenanza municipal tiene carácter preceptivo (obligatorio) y no vinculante (el Pleno puede apartarse de él).'}},
{n:102, q:'En los municipios de gran población, los proyectos de ordenanzas y reglamentos, salvo aquellos que regulen el Pleno y sus comisiones...', o:{a:'Son aprobados por la Junta de Gobierno Local.',b:'Son aprobados por el Alcalde.',c:'Son aprobados por la Comisión Especial de Sugerencias y Reclamaciones.',d:'Son aprobados por la Junta de Portavoces.'}, correct:'a', why:{a:'En los municipios de gran población, los proyectos de ordenanzas y reglamentos que no regulen el Pleno y sus comisiones son aprobados inicialmente por la Junta de Gobierno Local.'}},
{n:103, q:'En los municipios de gran población, se requiere informe del Consejo Social de la Ciudad, cuando la materia que regula el proyecto de ordenanza o reglamento versa sobre...', o:{a:'Desarrollo económico local.',b:'Planificación estratégica de la ciudad.',c:'Grandes proyectos urbanos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'En los municipios de gran población, el Consejo Social de la Ciudad debe emitir informe cuando el proyecto de ordenanza verse sobre desarrollo económico local, planificación estratégica o grandes proyectos urbanos.'}},
{n:104, q:'En cumplimiento de lo dispuesto en los artículos 132 y 133 de la Ley 39/2015 del Procedimiento Administrativo Común de las Administraciones Públicas, los proyectos de ordenanzas deberán...', o:{a:'Haber sido previstos en el Plan Normativo Anual de la administración competente.',b:'Ser objeto de consulta pública, a través del portal web de la administración competente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Los arts. 132 y 133 de la Ley 39/2015 exigen que los proyectos normativos figuren en el Plan Normativo Anual y sean objeto de consulta pública a través del portal web de la administración competente.'}},
{n:105, q:'De conformidad con lo dispuesto en el artículo 129 de la Ley 39/2015 del Procedimiento Administrativo Común de las Administraciones Públicas, al llevar a cabo la aprobación de normas reglamentarias, como son las ordenanzas y reglamentos, las administraciones...', o:{a:'Actuarán de acuerdo con los principios de necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia, y eficiencia.',b:'Justificarán la necesidad de esa norma por una razón de interés general, basándose en una identificación clara de los fines perseguidos y en que es el instrumento más adecuado para garantizar su consecución.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.129 Ley 39/2015 establece que en la aprobación de normas reglamentarias las Administraciones actuarán conforme a los principios de necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia y eficiencia, justificando el interés general.'}},
{n:106, q:'En aplicación del artículo 70 bis de la Ley 7/1985 reguladora del Régimen Local, los vecinos de un determinado municipio deciden ejercer la iniciativa popular y presentar un proyecto de ordenanza. Indique la respuesta correcta.', o:{a:'Solo pueden ejercer esta iniciativa los vecinos nacidos en este municipio.',b:'Solo pueden ejercer esta iniciativa los vecinos que gocen del derecho de sufragio activo en las elecciones municipales.',c:'Solo pueden ejercer esta iniciativa los vecinos que previamente se hayan inscrito en el censo electoral del municipio, y se hallen en alguna de las situaciones previstas en el artículo 114 de la Ley 39/2015.',d:'Solo puede ejercer esta iniciativa los vecinos que gocen del derecho de sufragio activo y pasivo en las elecciones municipales.'}, correct:'b', why:{b:'El art.70 bis LBRL establece que pueden ejercer la iniciativa popular para presentar proyectos de ordenanza los vecinos que gocen del derecho de sufragio activo en las elecciones municipales.'}},
{n:107, q:'En aplicación del artículo 70 bis de la Ley 7/1985 reguladora del Régimen Local, los vecinos de un municipio de 55.000 habitantes deciden ejercer la iniciativa popular y presentar un proyecto de ordenanza. Para que esta iniciativa prospere debe ir suscrita, al menos por...', o:{a:'El 20% de los vecinos del municipio.',b:'El 15% de los vecinos del municipio.',c:'El 10% de los vecinos del municipio.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art.70 bis LBRL establece que en municipios de hasta 5.000 hab. se requiere el 20%, de 5.001 a 20.000 hab. el 15%, y en municipios mayores el 10% de los vecinos con derecho a voto.'}},
{n:108, q:'Según el artículo 49 de la Ley 7/1985 reguladora del Régimen Local, una vez aprobado por el Pleno, el proyecto de ordenanza será sometida a información pública, para la presentación de reclamaciones y sugerencias, por un periodo de...', o:{a:'15 días.',b:'20 días.',c:'30 días.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art.49 LBRL establece que los proyectos de ordenanzas se someterán a información pública y audiencia de los interesados por el plazo mínimo de treinta días.'}},
{n:109, q:'Según el artículo 49 de la Ley 7/1985 reguladora del Régimen Local, si no se presentasen reclamaciones y/o sugerencias al borrador de ordenanza publicado tras su aprobación inicial por el Pleno...', o:{a:'Se procederá a una nueva aprobación plenaria en el plazo de los treinta días siguientes a la finalización del periodo de sugerencias y reclamaciones.',b:'Se entenderá definitivamente aprobado este acuerdo, que hasta ese momento era provisional.',c:'Se someterá a informe del Secretario de la Corporación, procediendo seguidamente a su aprobación definitiva en el primer pleno ordinario que tenga lugar.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art.49 LBRL establece que si no se presentan reclamaciones ni sugerencias en el período de información pública, el acuerdo inicial se entenderá definitivamente adoptado.'}},
{n:110, q:'Una vez aprobada definitivamente una Ordenanza Municipal ¿qué otro trámite debe seguir?', o:{a:'Remisión a la Delegación del Gobierno en la Comunidad Autónoma.',b:'Inscripción en el Registro de Actos Jurídicos Documentados.',c:'Publicación en el correspondiente Diario Oficial.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art.70.2 LBRL establece que las Ordenanzas, Reglamentos y demás acuerdos locales entrarán en vigor una vez publicados en el Boletín Oficial de la Provincia y haya transcurrido el plazo previsto en el art.65.2 de la misma ley.'}},
{n:111, q:'Una vez aprobada y publicada una ordenanza municipal, la Administración del Estado o de la Comunidad Autónoma podrán solicitar al Ayuntamiento su anulación o subsanación en el plazo de:', o:{a:'Un mes.',b:'15 días.',c:'10 días.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art.65 LBRL establece que si la Administración del Estado o la CCAA estimase que un acto o acuerdo de una Entidad Local infringe el ordenamiento jurídico, podrá requerir a dicha Entidad que anule el acto, indicándole el plazo máximo de un mes para que atienda el requerimiento.'}},
{n:112, q:'Una vez requerido un Ayuntamiento por la respectiva Comunidad Autónoma para que anule o subsane la Ordenanza aprobada, debe llevar a cabo lo solicitado en el plazo de:', o:{a:'Un mes.',b:'15 días.',c:'10 días.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art.65 LBRL establece que el requerimiento debe formular en el plazo de quince días, y la Entidad Local dispone de un mes para atenderlo.'}},
{n:113, q:'Por la materia que regulan, las ordenanzas municipales pueden clasificarse en:', o:{a:'De policía y buen gobierno, Fiscales y Urbanísticas.',b:'De policía y buen gobierno, Generales y Especiales.',c:'De policía y buen gobierno, de regulación interna y urgentes.',d:'Fiscales, Ambientales y Coactivas.'}, correct:'a', why:{a:'Por la materia que regulan, las Ordenanzas municipales se clasifican en: de policía y buen gobierno (conducta ciudadana), fiscales (tributos y precios públicos) y urbanísticas (edificación y uso del suelo).'}},
{n:114, q:'Las Ordenanzas Municipales de Policía y buen Gobierno son:', o:{a:'Un conjunto de medidas coactivas que sirven a los fines del municipio, la provincia o el Estado.',b:'Un conjunto de medidas coactivas arbitradas por el Derecho para que el particular ajuste su actividad a un fin de utilidad pública.',c:'Un conjunto de medidas coactivas y arbitrarias que persiguen que el ciudadano ajuste su actividad a los fines del Gobierno de la Nación.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Las Ordenanzas de Policía y Buen Gobierno son el conjunto de medidas coactivas arbitradas por el Derecho para que el particular ajuste su actividad a un fin de utilidad pública municipal.'}},
{n:115, q:'Las Ordenanzas que regulan las normas que deben observar los vecinos en el ejercicio de sus derechos de vecindad, se denominan:', o:{a:'Ordenanzas Fiscales.',b:'Ordenanzas especiales de convivencia y fraternidad.',c:'Ordenanzas de gobierno y administración del municipio.',d:'Ordenanzas de Policía y Buen Gobierno.'}, correct:'d', why:{d:'Las Ordenanzas de Policía y Buen Gobierno regulan las normas de convivencia, la conducta de los vecinos y el ejercicio de los derechos de vecindad en el municipio.'}},
{n:116, q:'Las Ordenanzas Fiscales de los Ayuntamientos son:', o:{a:'Un conjunto de medidas coactivas arbitradas por el Derecho para que el particular ajuste su actividad a un fin de utilidad pública.',b:'Un conjunto de normas arbitrarias que tratan de garantizar la supervivencia del municipio mediante el aseguramiento de los ingresos mínimos necesarios.',c:'Un conjunto de normas que regulan las exacciones municipales.',d:'El conjunto de normas tributarias y financieras que regulan la participación del municipio de los ingresos que le asignan los presupuestos Estatales y Autonómicos, y los gastos de un determinado ejercicio fiscal.'}, correct:'c', why:{c:'Las Ordenanzas Fiscales son el conjunto de normas que regulan las exacciones municipales (impuestos, tasas y contribuciones especiales), estableciendo los elementos esenciales de cada tributo local.'}},
{n:117, q:'Una Ordenanza Fiscal reguladora de una exacción municipal debe ser aprobada:', o:{a:'Por mayoría simple de la Junta de Gobierno Local en municipios de gran población y por idéntica mayoría del Pleno, en municipios que no son de gran población.',b:'Por mayoría absoluta del Pleno en municipios de gran población y por idéntica mayoría de la Junta de Gobierno Local en los municipios que no son de gran población.',c:'Por mayoría simple del Ayuntamiento Pleno en todo caso.',d:'Por mayoría absoluta del Ayuntamiento Pleno, en todo caso.'}, correct:'c', why:{c:'Las Ordenanzas Fiscales reguladoras de exacciones municipales se aprueban por mayoría simple del Pleno del Ayuntamiento en municipios no de gran población, y por la Junta de Gobierno Local en municipios de gran población.'}},
{n:118, q:'Los Bandos son normas dictadas y aprobadas por:', o:{a:'El Alcalde.',b:'El Alcalde en municipios de régimen común, y la Junta de Gobierno Local en municipios de gran población.',c:'La Junta de Gobierno Local.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'Los Bandos son disposiciones dictadas por el Alcalde en el ejercicio de sus competencias de gobierno y administración del municipio.'}},
{n:119, q:'La diferencia entre un Bando y una Ordenanza o Reglamento radica:', o:{a:'En el órgano que los dicta.',b:'En las materias que regulan.',c:'No existen diferencias.',d:'Las respuestas a y b son correctas.'}, correct:'d', why:{d:'La diferencia entre el Bando y la Ordenanza o Reglamento radica tanto en el órgano que los dicta (el Bando lo dicta el Alcalde; la Ordenanza o Reglamento, el Pleno) como en las materias que regulan.'}},
{n:120, q:'Los Alcaldes pueden dictar Bandos:', o:{a:'Sobre cualquier materia.',b:'Sólo sobre materias de titularidad exclusivamente municipal.',c:'Solamente para el desarrollo de sus propias competencias.',d:'Sobre las materias que le atribuya el Ayuntamiento Pleno al Alcalde.'}, correct:'c', why:{c:'Los Alcaldes solo pueden dictar Bandos en el ámbito de sus propias competencias, no pudiendo invadir las competencias de otros órganos municipales.'}},
{n:121, q:'Los Alcaldes pueden delegar la función de dictar Bandos en:', o:{a:'Los Tenientes de Alcalde.',b:'Los Concejales delegados del área de la materia que trate de regular el Bando.',c:'Cualquier miembro de la Corporación.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'La función de dictar Bandos es una competencia personal del Alcalde que no puede ser delegada, por su carácter propio de la jefatura municipal.'}},
{n:122, q:'Un Bando puede ejecutar una Ordenanza.', o:{a:'No, nunca.',b:'Sí, siempre.',c:'No, salvo que la Junta de Gobierno Local así lo determine.',d:'Sí, siempre que exista habilitación suficiente para ello.'}, correct:'d', why:{d:'Un Bando puede ejecutar y aplicar lo dispuesto en una Ordenanza, siempre que tenga habilitación suficiente para ello y el Alcalde actúe dentro de sus competencias.'}},
{n:123, q:'Para que un Bando pueda ser aplicado se requiere....', o:{a:'El mismo proceso que para la aprobación de una Ordenanza.',b:'Un acto de aprobación por el Alcalde en presencia del secretario de la corporación, previo informe de la comisión informativa correspondiente.',c:'Su publicación.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Para que un Bando sea aplicable y produzca efectos jurídicos, es necesaria su publicación, ya que las disposiciones de carácter general deben publicarse para su obligatoriedad.'}},
];
